@-moz-document domain("discord.com") {
/* =====================================================
   THEME VARIABLES
   ===================================================== */
:root {
  --accent: 207, 90, 255; /* neon purple (RGB) */
  --accent-hex: #CF5AFF;
  --accent-strong: rgba(var(--accent), 1);
  --accent-600: rgba(var(--accent), 0.85);
  --accent-500: rgba(var(--accent), 0.65);

  --bg-image: url("https://images.unsplash.com/photo-1504384308090-c894fdcc538d?q=80&w=1920&auto=format&fit=crop");
  --bg-blur: 16px;
  --bg-dim: 0.25;

  --round: 18px;
  --glass: rgba(10, 12, 20, 0.55);
  --glass-strong: rgba(10, 12, 20, 0.75);
  --glass-hover: rgba(20, 24, 36, 0.6);
  --border: 1px solid rgba(255, 255, 255, 0.06);
}

/* =====================================================
   GLOBAL WALLPAPER
   ===================================================== */
#app-mount::before {
  content: "";
  position: fixed;
  inset: 0;
  background-image: var(--bg-image);
  background-size: cover;
  background-position: center;
  background-attachment: fixed;
  filter: blur(var(--bg-blur));
  transform: scale(1.03);
  z-index: -2;
}
#app-mount::after {
  content: "";
  position: fixed;
  inset: 0;
  background: linear-gradient(120deg, rgba(5,6,10, calc(var(--bg-dim) + 0.25)) 0%, rgba(5,6,12, var(--bg-dim)) 100%);
  z-index: -1;
}

/* =====================================================
   SURFACES
   ===================================================== */
.container-2cd8Mz,
.sidebarRegionScroller-FXiQOh,
.contentRegionScroller-2_GT_N,
.scroller-WSmht3,
.panels-3wFtMD,
.members-3WRCEx,
.channelTextArea-1FufC0 {
  background: transparent !important;
}

.card-2TuZPZ,
.message-2CShn3,
.searchBar-3TnChZ,
.scrollableContainer-15eg7h {
  backdrop-filter: blur(var(--bg-blur));
  background: var(--glass);
  border: var(--border);
  border-radius: var(--round);
}
.message-2CShn3:hover { background: var(--glass-hover); }

/* =====================================================
   CHAT / MENTIONS
   ===================================================== */
.mentioned-Tre-dv {
  background: linear-gradient(90deg, rgba(var(--accent),0.12), transparent);
  border-left: 3px solid var(--accent-600);
}
.mention {
  background: var(--accent-500) !important;
  color: #fff !important;
}

/* =====================================================
   BUTTONS
   ===================================================== */
.lookFilled-1Gx00P.colorBrand-2M3O3N {
  background: linear-gradient(135deg, var(--accent-600), var(--accent-strong)) !important;
  border: none !important;
  box-shadow: 0 8px 20px -8px var(--accent-500);
}
.lookFilled-1Gx00P:hover { filter: brightness(1.05); }

/* =====================================================
   SCROLLBARS
   ===================================================== */
::-webkit-scrollbar { width: 10px; }
::-webkit-scrollbar-thumb {
  background: rgba(255,255,255,0.25);
  border-radius: 999px;
}
::-webkit-scrollbar-track { background: transparent; }
}
